# 순차 탐색
items = ["검", "방패", "물약"]
for i in range(len(items)):
    if items[i] == "물약":
        print(i)   # 2

# 이진 탐색 (정렬된 리스트 전용)
numbers = [3, 7, 12, 18, 23]
low, high = 0, len(numbers) - 1
while low <= high:
    mid = (low + high) // 2
    if numbers[mid] == 18:
        print(mid)       # 3
        break
    elif numbers[mid] < 18:
        low = mid + 1
    else:
        high = mid - 1

